def peek_top(stack):
    if not stack:
        return False, None
    return True, stack[-1]

for stack in [[], [None], [1, 2, 2]]:
    print(peek_top(stack), stack)

def bounded_push(stack, value, limit):
    if len(stack) >= limit:
        return False
    stack.append(value)
    return True

for stack, value, limit in [([], 9, 0), ([1], 1, 1), ([None], None, 2)]:
    print(bounded_push(stack, value, limit), stack)

def run_stack(actions):
    stack = []
    replies = []
    for action, value in actions:
        if action == "push":
            stack.append(value)
        elif not stack:
            replies.append((False, None))
        elif action == "pop":
            replies.append((True, stack.pop()))
        else:
            replies.append((True, stack[-1]))
    return replies, stack

for actions in [[], [("pop", None)], [("push", None), ("peek", None), ("pop", None)], [("push", 1), ("push", 2), ("peek", None), ("pop", None)]]:
    print(run_stack(actions))
